+CREATE USER 20553132_u2@localhost;
+CREATE USER '20553132_u3'@'%';
+GRANT ALL ON *.* TO 20553132_u1@localhost;
+ALTER USER 20553132_u1@localhost PASSWORD EXPIRE;
